"use client";

import Link from "next/link";
import { AlertTriangle, ArrowLeft, ArrowRight, BookOpenCheck, CalendarClock, CheckCircle2, ClipboardCheck, Download, Droplets, FileClock, Gauge, Loader2, Plus, RefreshCw, Settings2, ShieldCheck, Thermometer, TriangleAlert, X } from "lucide-react";
import { useState } from "react";
import { BrandMark } from "@/components/brand/brand-mark";
import { QUALITY_TEMPLATE_LIBRARY, type QualityTemplateLibraryPreset } from "@/constants/quality-template-library";
import { QualityLogCapture } from "@/components/quality/quality-log-capture";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { qualityMutation, useQualityQuery } from "@/hooks/use-quality";
import type { OperationalQualityFieldType, QualitySnapshot, QualityTemplateRoot, QualityTemplateVersion } from "@/types";

type Tab = "logs" | "actions" | "schedules" | "templates";
interface FieldDraft { key: string; code: string; label: string; description: string; fieldType: OperationalQualityFieldType; unit: string; minimum: string; maximum: string; expectedBoolean: boolean; options: string; nonCompliantOptions: string; required: boolean; severity: "warning" | "critical"; evidenceRequired: boolean }
interface TemplateDraft { templateVersionId: string | null; rootTemplateId: string | null; expectedVersion: number; branchId: string; code: string; name: string; category: string; instructions: string; scheduleType: string; defaultDueTime: string; fields: FieldDraft[] }
interface RecurrenceDraft { branchId: string; templateVersionId: string; shiftId: string; scheduleType: "daily" | "per_shift" | "days" | "multiple_daily" | "interval"; daysOfWeek: number[]; timesText: string; intervalMinutes: string; startDate: string; endDate: string; }

export function QualityCenterScreen({ organizationId, branchId, period = "today", initialLogId }: { organizationId?: string; branchId?: string; period?: string; initialLogId?: string }) {
  const params = new URLSearchParams();
  if (organizationId) params.set("organizationId", organizationId);
  if (branchId) params.set("branchId", branchId);
  if (period) params.set("period", period);
  if (initialLogId) params.set("logId", initialLogId);
  const { data: snapshot, error, loading, refresh } = useQualityQuery<QualitySnapshot>(params.toString());
  const [tab, setTab] = useState<Tab>("logs");
  const [templateDraft, setTemplateDraft] = useState<TemplateDraft | null>(null);
  const [scheduleOpen, setScheduleOpen] = useState(false);
  const [recurrenceOpen, setRecurrenceOpen] = useState(false);
  const [recurrence, setRecurrence] = useState<RecurrenceDraft>({ branchId: branchId ?? "", templateVersionId: "", shiftId: "", scheduleType: "daily", daysOfWeek: [1, 2, 3, 4, 5], timesText: "12:00", intervalMinutes: "60", startDate: todayInput(), endDate: "" });
  const [schedule, setSchedule] = useState({ branchId: branchId ?? "", templateVersionId: "", shiftId: "", operationalDate: todayInput(), dueTime: "12:00" });
  const [revision, setRevision] = useState<{ version: QualityTemplateVersion; reason: string } | null>(null);
  const [busy, setBusy] = useState(false);
  const [feedback, setFeedback] = useState<{ tone: "error" | "success"; text: string } | null>(null);
  const [logStatus, setLogStatus] = useState("open");

  if (loading && !snapshot) return <FullState loading title="Preparando Calidad" detail="Revalidando organización, membresía, permisos, alcance y datos persistentes." />;
  if (error || !snapshot) return <FullState title="No fue posible abrir Calidad" detail={error ?? "La información no está disponible."} />;
  const selectedLog = initialLogId ? snapshot.logs.find((log) => log.id === initialLogId) : null;
  const backHref = `/app/calidad?organizationId=${encodeURIComponent(snapshot.organization.id)}${snapshot.selectedBranchId ? `&branchId=${encodeURIComponent(snapshot.selectedBranchId)}` : ""}&period=${encodeURIComponent(period)}`;
  if (initialLogId && selectedLog) return <QualityLogCapture snapshot={snapshot} log={selectedLog} backHref={backHref} refresh={refresh} />;
  if (initialLogId && !selectedLog) return <FullState title="Bitácora no encontrada" detail="No existe o está fuera de tu organización, permisos o alcance de sucursal." />;

  const publishedVersions = snapshot.templates.flatMap((root) => root.versions.filter((version) => version.status === "published"));
  const visibleLogs = snapshot.logs.filter((log) => {
    if (logStatus === "all") return true;
    if (logStatus === "open") return ["pending", "in_progress", "overdue"].includes(log.status);
    return log.status === logStatus;
  });
  const selectedScheduleTemplate = publishedVersions.find((version) => version.id === schedule.templateVersionId);
  const applicableTemplates = publishedVersions.filter((version) => !schedule.branchId || !version.rootBranchId || version.rootBranchId === schedule.branchId);
  const applicableShifts = snapshot.shifts.filter((shift) => !schedule.branchId || !shift.branchId || shift.branchId === schedule.branchId);

  const perform = async (operation: () => Promise<void>, success: string) => {
    setBusy(true); setFeedback(null);
    try { await operation(); await refresh(); setFeedback({ tone: "success", text: success }); }
    catch (caught) { setFeedback({ tone: "error", text: caught instanceof Error ? caught.message : "No fue posible guardar." }); }
    finally { setBusy(false); }
  };

  const navigateFilters = (next: { organizationId?: string; branchId?: string; period?: string }) => {
    const query = new URLSearchParams({ organizationId: next.organizationId ?? snapshot.organization.id, period: next.period ?? period });
    const nextBranch = next.branchId === undefined ? snapshot.selectedBranchId : next.branchId === "all" ? null : next.branchId;
    if (nextBranch) query.set("branchId", nextBranch);
    window.location.assign(`/app/calidad?${query.toString()}`);
  };

  const openNewTemplate = (root?: QualityTemplateRoot) => setTemplateDraft({
    templateVersionId: null, rootTemplateId: root?.id ?? null, expectedVersion: 0,
    branchId: root?.branchId ?? snapshot.selectedBranchId ?? snapshot.branches[0]?.id ?? "",
    code: root?.code ?? "", name: root?.name ?? "", category: "temperature", instructions: "", scheduleType: "daily", defaultDueTime: "12:00",
    fields: [emptyField("Temperatura", "number", "°C")],
  });
  const openLibraryPreset = (preset: QualityTemplateLibraryPreset) => setTemplateDraft({
    templateVersionId: null, rootTemplateId: null, expectedVersion: 0,
    branchId: snapshot.selectedBranchId ?? snapshot.branches[0]?.id ?? "all",
    code: preset.code, name: preset.name, category: preset.category, instructions: `${preset.instructions}\n\nAntes de publicar, el responsable de inocuidad debe revisar y aprobar criterios, límites y frecuencia.`, scheduleType: preset.scheduleType, defaultDueTime: preset.defaultDueTime ?? "12:00",
    fields: preset.fields.map((field) => ({ key: crypto.randomUUID(), code: "", label: field.label, description: "", fieldType: field.fieldType, unit: field.unit ?? "", minimum: "", maximum: "", expectedBoolean: field.expectedBoolean ?? true, options: (field.options ?? ["Conforme", "No conforme"]).join(", "), nonCompliantOptions: field.fieldType === "select" ? (field.options?.filter((option) => /no conforme|rechaz|reten|crít/i.test(option)).join(", ") ?? "") : "", required: true, severity: field.severity ?? "warning", evidenceRequired: field.evidenceRequired ?? false })),
  });
  const openDraft = (version: QualityTemplateVersion) => setTemplateDraft({
    templateVersionId: version.id, rootTemplateId: version.rootTemplateId, expectedVersion: version.version, branchId: version.rootBranchId ?? "all",
    code: version.code, name: version.name, category: version.category, instructions: version.instructions, scheduleType: version.scheduleType, defaultDueTime: version.defaultDueTime ?? "",
    fields: version.fields.map((field) => ({ key: field.id, code: field.code, label: field.label, description: field.description, fieldType: field.fieldType, unit: field.unit ?? "", minimum: field.minimum === null ? "" : String(field.minimum), maximum: field.maximum === null ? "" : String(field.maximum), expectedBoolean: field.expectedBoolean ?? true, options: field.options.join(", "), nonCompliantOptions: field.nonCompliantOptions.join(", "), required: field.required, severity: field.deviationSeverity, evidenceRequired: field.evidenceRequiredOnDeviation })),
  });

  const saveTemplate = async () => {
    if (!templateDraft) return;
    const body = templatePayload(snapshot.organization.id, templateDraft);
    await perform(async () => {
      if (templateDraft.templateVersionId) await qualityMutation("update_template", { ...body, templateVersionId: templateDraft.templateVersionId, expectedVersion: templateDraft.expectedVersion });
      else await qualityMutation("create_template", { ...body, rootTemplateId: templateDraft.rootTemplateId, branchId: templateDraft.branchId === "all" ? null : templateDraft.branchId, idempotencyKey: crypto.randomUUID() });
      setTemplateDraft(null);
    }, "El borrador de la plantilla quedó guardado.");
  };

  const scheduleLog = async () => {
    await perform(async () => {
      if (!schedule.branchId || !schedule.templateVersionId) throw new Error("Selecciona sucursal y plantilla publicada.");
      if (selectedScheduleTemplate?.scheduleType === "per_shift" && !schedule.shiftId) throw new Error("Selecciona el turno.");
      const timezone = snapshot.branches.find((branch) => branch.id === schedule.branchId)?.timezone ?? snapshot.organization.timezone;
      const dueAt = zonedDateTimeToIso(schedule.operationalDate, schedule.dueTime, timezone);
      const result = await qualityMutation<{ logId: string }>("schedule_log", { organizationId: snapshot.organization.id, branchId: schedule.branchId, templateVersionId: schedule.templateVersionId, shiftId: schedule.shiftId || null, operationalDate: schedule.operationalDate, dueAt, assignedToMembershipId: snapshot.membership.id, idempotencyKey: crypto.randomUUID() });
      window.location.assign(`/app/calidad/${encodeURIComponent(result.logId)}?organizationId=${encodeURIComponent(snapshot.organization.id)}`);
    }, "La bitácora quedó programada.");
  };

  const createRecurrence = async () => {
    await perform(async () => {
      if (!recurrence.branchId || !recurrence.templateVersionId) throw new Error("Selecciona sucursal y plantilla publicada.");
      if (recurrence.scheduleType === "per_shift" && !recurrence.shiftId) throw new Error("Selecciona el turno de esta recurrencia.");
      const timezone = snapshot.branches.find((branch) => branch.id === recurrence.branchId)?.timezone ?? snapshot.organization.timezone;
      const times = recurrence.timesText.split(",").map((value) => value.trim()).filter(Boolean);
      const result = await qualityMutation<{ ruleId: string }>("create_schedule_rule", {
        organizationId: snapshot.organization.id,
        branchId: recurrence.branchId,
        templateVersionId: recurrence.templateVersionId,
        shiftId: recurrence.shiftId || null,
        assignedToMembershipId: snapshot.membership.id,
        scheduleType: recurrence.scheduleType,
        daysOfWeek: recurrence.scheduleType === "days" ? recurrence.daysOfWeek : [],
        times,
        intervalMinutes: recurrence.scheduleType === "interval" ? Number(recurrence.intervalMinutes) : null,
        timezone,
        startDate: recurrence.startDate,
        endDate: recurrence.endDate || null,
        idempotencyKey: crypto.randomUUID(),
      });
      const throughDate = minDate(recurrence.endDate || addDaysInput(recurrence.startDate, 6), addDaysInput(recurrence.startDate, 30));
      await qualityMutation("generate_schedule_rule", { organizationId: snapshot.organization.id, ruleId: result.ruleId, throughDate, idempotencyKey: crypto.randomUUID() });
      setRecurrenceOpen(false);
    }, "La recurrencia quedó creada y sus primeras bitácoras fueron generadas.");
  };

  const generateRule = async (ruleId: string, fromDate: string | null, endDate: string | null) => {
    await perform(async () => {
      const start = fromDate ? addDaysInput(fromDate, 1) : todayInput();
      const throughDate = minDate(endDate || addDaysInput(start, 6), addDaysInput(start, 6));
      await qualityMutation("generate_schedule_rule", { organizationId: snapshot.organization.id, ruleId, throughDate, idempotencyKey: crypto.randomUUID() });
    }, "Se generaron las próximas bitácoras sin duplicar instancias existentes.");
  };

  return <main className="min-h-screen bg-[#edf4f7] pb-24 text-[#153650] lg:pb-12">
    <header className="sticky top-0 z-30 border-b border-[#d4e3ea] bg-white/95 backdrop-blur"><div className="mx-auto flex min-h-18 max-w-[1500px] items-center justify-between gap-3 px-4 py-3 sm:px-6 xl:px-9"><div className="flex min-w-0 items-center gap-3"><Button asChild variant="ghost" size="icon" className="size-10 rounded-xl"><Link href={`/app?organizationId=${encodeURIComponent(snapshot.organization.id)}`} aria-label="Volver al tablero"><ArrowLeft className="size-4" /></Link></Button><BrandMark compact /><div className="min-w-0"><p className="truncate text-sm font-black">Centro de calidad</p><p className="truncate text-xs text-[#6b8194]">{snapshot.organization.name}</p></div></div><div className="flex items-center gap-2"><Button variant="ghost" size="icon" className="size-11 rounded-xl" disabled={busy} onClick={() => void refresh()} aria-label="Actualizar"><RefreshCw className={`size-4 ${busy ? "animate-spin" : ""}`} /></Button>{snapshot.capabilities.capture && <Button className="hidden min-h-11 rounded-xl bg-[#1769df] font-extrabold sm:inline-flex" disabled={!publishedVersions.length} onClick={() => { setSchedule((current) => ({ ...current, branchId: current.branchId || snapshot.selectedBranchId || snapshot.branches[0]?.id || "", templateVersionId: current.templateVersionId || publishedVersions[0]?.id || "" })); setScheduleOpen(true); }}><Plus className="size-4" />Nueva captura</Button>}</div></div></header>
    <div className="mx-auto max-w-[1500px] space-y-6 p-4 sm:p-6 xl:p-9">
      <section className="relative overflow-hidden rounded-[2rem] bg-[#0b2e4b] p-6 text-white shadow-[0_24px_65px_rgba(14,47,76,.17)] sm:p-8"><div className="pointer-events-none absolute -right-20 -top-24 size-72 rounded-full bg-[#20c9c2]/20 blur-3xl" /><div className="relative flex flex-col justify-between gap-6 xl:flex-row xl:items-end"><div><div className="flex flex-wrap gap-2 text-xs font-bold text-[#a4d3d3]"><span className="rounded-full bg-white/10 px-3 py-1">{snapshot.organization.code}</span><span className="rounded-full bg-white/10 px-3 py-1">Datos persistentes</span><span className="rounded-full bg-white/10 px-3 py-1">Alcance autorizado</span></div><h1 className="mt-5 text-3xl font-black tracking-[-.045em] sm:text-4xl">Inocuidad que se puede demostrar.</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[#b9ccd8]">Programa controles, captura mediciones, detecta desviaciones y conserva evidencia sin alterar el historial.</p></div><div className="grid grid-cols-2 gap-2 sm:grid-cols-4"><HeroMetric value={snapshot.metrics.pendingLogs + snapshot.metrics.inProgressLogs} label="Por capturar" /><HeroMetric value={snapshot.metrics.completedInPeriod} label="Completadas" /><HeroMetric value={snapshot.metrics.deviationsInPeriod} label="Desviaciones" /><HeroMetric value={snapshot.metrics.openCorrectiveActions} label="Acciones abiertas" /></div></div></section>
      {snapshot.capabilities.restricted && <Notice tone="info" text="La organización está restringida: Calidad permanece disponible únicamente para consulta." />}
      {feedback && <Notice tone={feedback.tone} text={feedback.text} />}

      <section className="grid gap-3 rounded-[1.4rem] border border-[#d5e4eb] bg-white p-4 shadow-sm md:grid-cols-[1fr_1fr_auto]"><select className="h-11 rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm font-bold" value={snapshot.selectedBranchId ?? "all"} onChange={(event) => navigateFilters({ branchId: event.target.value })}><option value="all">Todas las sucursales autorizadas</option>{snapshot.branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select><select className="h-11 rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm font-bold" value={period} onChange={(event) => navigateFilters({ period: event.target.value })}><option value="today">Hoy</option><option value="last_7_days">Últimos 7 días</option><option value="last_30_days">Últimos 30 días</option></select>{snapshot.availableOrganizations.length > 1 && <select className="h-11 rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm font-bold" value={snapshot.organization.id} onChange={(event) => navigateFilters({ organizationId: event.target.value, branchId: "all" })}>{snapshot.availableOrganizations.map((organization) => <option key={organization.id} value={organization.id}>{organization.name}</option>)}</select>}</section>
      {snapshot.capabilities.exportReports && <section className="flex flex-col justify-between gap-3 rounded-[1.4rem] border border-[#d5e4eb] bg-white p-4 shadow-sm sm:flex-row sm:items-center"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#168b95]">Reporte mensual</p><p className="mt-1 text-sm text-[#6b8093]">Exporta el mes calendario actual dentro del alcance autorizado, con métricas, sucursales, bitácoras y acciones.</p></div><div className="flex flex-wrap gap-2"><Button asChild variant="outline" className="rounded-xl"><a href={`/api/customer/quality/export?report=monthly&organizationId=${encodeURIComponent(snapshot.organization.id)}${snapshot.selectedBranchId ? `&branchId=${encodeURIComponent(snapshot.selectedBranchId)}` : ""}&format=pdf`}><Download className="size-4" />PDF</a></Button><Button asChild variant="outline" className="rounded-xl"><a href={`/api/customer/quality/export?report=monthly&organizationId=${encodeURIComponent(snapshot.organization.id)}${snapshot.selectedBranchId ? `&branchId=${encodeURIComponent(snapshot.selectedBranchId)}` : ""}&format=xlsx`}>XLSX</a></Button><Button asChild variant="outline" className="rounded-xl"><a href={`/api/customer/quality/export?report=monthly&organizationId=${encodeURIComponent(snapshot.organization.id)}${snapshot.selectedBranchId ? `&branchId=${encodeURIComponent(snapshot.selectedBranchId)}` : ""}&format=csv`}>CSV</a></Button></div></section>}

      <section className="grid grid-cols-2 gap-3 sm:grid-cols-3 xl:grid-cols-6"><Metric icon={Gauge} label="Cumplimiento a tiempo" value={snapshot.metrics.compliancePercent === null ? "Sin exigibles" : `${snapshot.metrics.compliancePercent.toFixed(1)}%`} /><Metric icon={BookOpenCheck} label="Plantillas publicadas" value={snapshot.metrics.publishedTemplates} /><Metric icon={CalendarClock} label="Programadas en periodo" value={snapshot.metrics.scheduledInPeriod} /><Metric icon={AlertTriangle} label="Bitácoras vencidas" value={snapshot.metrics.overdueLogs} alert={snapshot.metrics.overdueLogs > 0} /><Metric icon={FileClock} label="En captura" value={snapshot.metrics.inProgressLogs} /><Metric icon={CheckCircle2} label="Completadas" value={snapshot.metrics.completedInPeriod} /><Metric icon={TriangleAlert} label="Desviaciones" value={snapshot.metrics.deviationsInPeriod} alert={snapshot.metrics.deviationsInPeriod > 0} /><Metric icon={TriangleAlert} label="Desviaciones críticas" value={snapshot.metrics.criticalDeviationsInPeriod} alert={snapshot.metrics.criticalDeviationsInPeriod > 0} /><Metric icon={ClipboardCheck} label="Acciones abiertas" value={snapshot.metrics.openCorrectiveActions} alert={snapshot.metrics.openCorrectiveActions > 0} /><Metric icon={AlertTriangle} label="Acciones vencidas" value={snapshot.metrics.overdueCorrectiveActions} alert={snapshot.metrics.overdueCorrectiveActions > 0} /><Metric icon={RefreshCw} label="Grupos reincidentes" value={snapshot.metrics.recurrentDeviationGroups} alert={snapshot.metrics.recurrentDeviationGroups > 0} /><Metric icon={FileClock} label="Resolución promedio" value={snapshot.metrics.averageResolutionMinutes === null ? "Sin datos" : `${Math.round(snapshot.metrics.averageResolutionMinutes)} min`} /></section>

      <div className="flex gap-1 overflow-x-auto rounded-2xl border border-[#d5e4eb] bg-white p-1.5"><TabButton active={tab === "logs"} onClick={() => setTab("logs")} icon={ClipboardCheck} label="Bitácoras" count={snapshot.logs.length} /><TabButton active={tab === "actions"} onClick={() => setTab("actions")} icon={TriangleAlert} label="Acciones correctivas" count={snapshot.correctiveActions.filter((item) => ["open", "in_progress"].includes(item.status)).length} /><TabButton active={tab === "schedules"} onClick={() => setTab("schedules")} icon={CalendarClock} label="Recurrencias" count={snapshot.scheduleRules.length} /><TabButton active={tab === "templates"} onClick={() => setTab("templates")} icon={Settings2} label="Plantillas" count={snapshot.templates.length} /></div>

      {tab === "logs" && <section><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#168b95]">Trabajo del turno</p><h2 className="mt-1 text-2xl font-black">Bitácoras</h2></div><div className="flex gap-2"><select className="h-11 rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm font-bold" value={logStatus} onChange={(event) => setLogStatus(event.target.value)}><option value="open">Por atender</option><option value="completed">Cerradas</option><option value="cancelled">Canceladas</option><option value="all">Todas</option></select>{snapshot.capabilities.capture && <Button className="min-h-11 rounded-xl bg-[#1769df] font-bold sm:hidden" disabled={!publishedVersions.length} onClick={() => { setSchedule((current) => ({ ...current, branchId: current.branchId || snapshot.selectedBranchId || snapshot.branches[0]?.id || "", templateVersionId: current.templateVersionId || publishedVersions[0]?.id || "" })); setScheduleOpen(true); }}><Plus className="size-4" />Nueva</Button>}</div></div>{visibleLogs.length ? <div className="mt-4 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{visibleLogs.map((log) => <Link key={log.id} href={`/app/calidad/${encodeURIComponent(log.id)}?organizationId=${encodeURIComponent(snapshot.organization.id)}`} className={`group rounded-[1.45rem] border bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md ${log.deviationCount ? "border-[#efc2b3]" : "border-[#d5e4eb]"}`}><div className="flex items-start justify-between gap-3"><div className={`flex size-11 items-center justify-center rounded-2xl ${log.templateCategory === "temperature" ? "bg-[#e9f3ff] text-[#1769df]" : log.templateCategory === "water" ? "bg-[#e5f8f6] text-[#118b87]" : "bg-[#f1efff] text-[#6653b5]"}`}>{log.templateCategory === "temperature" ? <Thermometer className="size-5" /> : log.templateCategory === "water" ? <Droplets className="size-5" /> : <ClipboardCheck className="size-5" />}</div><Badge variant={log.deviationCount ? "destructive" : "secondary"}>{statusLabel(log.status)}</Badge></div><h3 className="mt-4 font-black text-[#24445e]">{log.templateName}</h3><p className="mt-1 text-sm text-[#6b8093]">{log.branchName} · {log.operationalDate}</p><div className="mt-5 flex items-end justify-between gap-3"><div><strong className="text-2xl text-[#173b58]">{log.completionPercentage}%</strong><p className="text-xs text-[#80919e]">avance</p></div><div className="text-right text-xs text-[#718699]"><p>{log.deviationCount} desviación(es)</p><p className="mt-1">Vence {new Date(log.dueAt).toLocaleString("es-MX")}</p></div></div><span className="mt-4 inline-flex items-center gap-1 text-xs font-extrabold text-[#1769df]">Abrir bitácora <ArrowRight className="size-3.5 transition group-hover:translate-x-0.5" /></span></Link>)}</div> : <Empty icon={ClipboardCheck} title="No hay bitácoras en esta vista" detail={publishedVersions.length ? "Programa la siguiente captura para comenzar el registro persistente." : "Publica primero una plantilla estructurada."} />}</section>}

      {tab === "actions" && <section><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#168b95]">Seguimiento verificable</p><h2 className="mt-1 text-2xl font-black">Acciones correctivas</h2></div>{snapshot.correctiveActions.length ? <div className="mt-4 space-y-3">{snapshot.correctiveActions.map((action) => <Link key={action.id} href={`/app/calidad/${encodeURIComponent(action.logInstanceId)}?organizationId=${encodeURIComponent(snapshot.organization.id)}`} className={`flex flex-col justify-between gap-4 rounded-[1.35rem] border bg-white p-5 transition hover:shadow-md sm:flex-row sm:items-center ${action.severity === "critical" ? "border-[#efb39f]" : "border-[#ead9ac]"}`}><div><div className="flex gap-2"><Badge className={action.severity === "critical" ? "bg-[#f2c4b5] text-[#8e321a]" : "bg-[#f8e8b9] text-[#73500a]"}>{action.severity === "critical" ? "Crítica" : "Advertencia"}</Badge><Badge variant="outline">{correctiveStatusLabel(action.status)}</Badge></div><h3 className="mt-3 font-black">{action.title}</h3><p className="mt-1 text-sm text-[#6b8093]">{action.branchName} · {action.description}</p></div><div className="text-sm text-[#6b8093] sm:text-right"><p>{action.assignedToName ?? "Sin responsable"}</p><p className="mt-1">{action.dueAt ? `Vence ${new Date(action.dueAt).toLocaleString("es-MX")}` : "Sin vencimiento"}</p></div></Link>)}</div> : <Empty icon={CheckCircle2} title="Sin acciones correctivas" detail="No hay desviaciones con seguimiento en el periodo y alcance seleccionados." />}</section>}

      {tab === "schedules" && <section><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#168b95]">Programación durable</p><h2 className="mt-1 text-2xl font-black">Recurrencias de bitácoras</h2><p className="mt-2 max-w-2xl text-sm text-[#6b8093]">Las reglas generan las mismas bitácoras productivas del Centro de Calidad y usan claves idempotentes para no duplicarlas.</p></div>{snapshot.capabilities.capture && <Button className="min-h-11 rounded-xl bg-[#0b8f87] font-bold" disabled={!publishedVersions.length} onClick={() => { const nextBranch = snapshot.selectedBranchId || snapshot.branches[0]?.id || ""; setRecurrence((current) => ({ ...current, branchId: current.branchId || nextBranch, templateVersionId: current.templateVersionId || publishedVersions.find((version) => !version.rootBranchId || version.rootBranchId === nextBranch)?.id || "" })); setRecurrenceOpen(true); }}><Plus className="size-4" />Nueva recurrencia</Button>}</div>{snapshot.scheduleRules.length ? <div className="mt-4 grid gap-4 lg:grid-cols-2">{snapshot.scheduleRules.map((rule) => <article key={rule.id} className="rounded-[1.45rem] border border-[#d5e4eb] bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wide text-[#168b95]">{rule.branchName}</p><h3 className="mt-1 font-black">{rule.templateName}</h3></div><Badge variant={rule.status === "active" ? "secondary" : "outline"}>{rule.status === "active" ? "Activa" : rule.status}</Badge></div><div className="mt-4 grid grid-cols-2 gap-2 text-sm"><SummaryCard label="Frecuencia" value={recurrenceLabel(rule.scheduleType)} /><SummaryCard label="Horario" value={rule.scheduleType === "interval" ? `${rule.times.join(" → ")} / ${rule.intervalMinutes ?? 0} min` : rule.times.join(", ") || "Ad hoc"} /><SummaryCard label="Inicio" value={rule.startDate} /><SummaryCard label="Generado hasta" value={rule.lastGeneratedThrough ?? "Aún no"} /></div>{rule.scheduleType === "days" && <p className="mt-3 text-xs text-[#718699]">Días: {rule.daysOfWeek.map(dayLabel).join(", ")}</p>}{rule.endDate && <p className="mt-1 text-xs text-[#718699]">Finaliza: {rule.endDate}</p>}{snapshot.capabilities.capture && rule.status === "active" && <Button variant="outline" className="mt-4 min-h-10 rounded-xl" disabled={busy} onClick={() => void generateRule(rule.id, rule.lastGeneratedThrough, rule.endDate)}><RefreshCw className="size-4" />Generar próximos 7 días</Button>}</article>)}</div> : <Empty icon={CalendarClock} title="Aún no hay recurrencias" detail="Crea una regla diaria, por turno, por días, varias veces al día o por intervalo." />}</section>}

      {tab === "templates" && <section>
        <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#168b95]">Catálogo versionado</p><h2 className="mt-1 text-2xl font-black">Plantillas de calidad</h2></div>{snapshot.capabilities.configureTemplates && <Button className="min-h-11 rounded-xl bg-[#0b8f87] font-bold" onClick={() => openNewTemplate()}><Plus className="size-4" />Nueva plantilla</Button>}</div>
        {snapshot.capabilities.configureTemplates && <div className="mt-4 rounded-[1.45rem] border border-[#cfe1e7] bg-[#f8fcfd] p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-extrabold uppercase tracking-[.14em] text-[#168b95]">Biblioteca inicial</p><h3 className="mt-1 text-lg font-black">Controles configurables</h3><p className="mt-1 max-w-3xl text-xs leading-5 text-[#718699]">Son borradores de arranque, no certificaciones ni criterios regulatorios automáticos. KitchenMind deja los límites numéricos sin fijar para que el responsable de inocuidad de cada organización los apruebe antes de publicar.</p></div><Badge variant="secondary">{QUALITY_TEMPLATE_LIBRARY.length} presets</Badge></div><div className="mt-4 flex gap-2 overflow-x-auto pb-1">{QUALITY_TEMPLATE_LIBRARY.map((preset) => <button key={preset.code} type="button" onClick={() => openLibraryPreset(preset)} className="min-w-52 rounded-xl border border-[#d4e3ea] bg-white p-3 text-left transition hover:border-[#4fb3b4] hover:shadow-sm"><span className="text-[10px] font-extrabold uppercase tracking-wide text-[#168b95]">{categoryLabel(preset.category)}</span><strong className="mt-1 block text-sm text-[#24445e]">{preset.name}</strong><span className="mt-2 block text-xs text-[#718699]">{recurrenceLabel(preset.scheduleType)}</span></button>)}</div></div>}
        <div className="mt-4 grid gap-4 lg:grid-cols-2">
          {snapshot.templates.map((root) => <article key={root.id} className="rounded-[1.45rem] border border-[#d5e4eb] bg-white p-5 shadow-sm">
            <div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wide text-[#168b95]">{root.code}</p><h3 className="mt-1 text-lg font-black">{root.name}</h3><p className="mt-1 text-xs text-[#718699]">{root.branchId ? snapshot.branches.find((branch) => branch.id === root.branchId)?.name ?? "Sucursal" : "Todas las sucursales"}</p></div><Badge variant="secondary">{root.versions.length} versión(es)</Badge></div>
            {root.versions.length ? <div className="mt-4 space-y-2">{root.versions.map((version) => <div key={version.id} className="rounded-xl bg-[#f5f9fb] p-3">
              <div className="flex flex-wrap items-center justify-between gap-2"><div><strong className="text-sm">Versión {version.versionNumber}</strong><span className="ml-2 text-xs text-[#718699]">{version.fields.length} campos · {categoryLabel(version.category)}</span></div><Badge className={templateStatusStyle(version.status)}>{templateStatusLabel(version.status)}</Badge></div>
              {snapshot.capabilities.configureTemplates && <div className="mt-3 flex flex-wrap gap-2">{version.status === "draft" ? <><Button size="sm" variant="outline" className="rounded-lg" onClick={() => openDraft(version)}>Editar</Button><Button size="sm" className="rounded-lg bg-[#1769df]" disabled={busy} onClick={() => void perform(async () => { await qualityMutation("publish_template", { organizationId: snapshot.organization.id, templateVersionId: version.id, expectedVersion: version.version }); }, "La versión quedó publicada e inmutable.")}>Publicar</Button></> : version.status === "published" ? <Button size="sm" variant="outline" className="rounded-lg" onClick={() => setRevision({ version, reason: "" })}>Crear nueva versión</Button> : null}</div>}
            </div>)}</div> : <div className="mt-4 rounded-xl border border-dashed border-[#bfd1da] p-4"><p className="text-sm font-bold">Estructura pendiente</p><p className="mt-1 text-xs text-[#718699]">Esta referencia vino del onboarding y todavía no define campos ni rangos.</p>{snapshot.capabilities.configureTemplates && <Button size="sm" variant="outline" className="mt-3 rounded-lg" onClick={() => openNewTemplate(root)}>Estructurar</Button>}</div>}
          </article>)}
          {!snapshot.templates.length && <div className="lg:col-span-2"><Empty icon={BookOpenCheck} title="Aún no hay plantillas" detail="Crea una plantilla, revisa sus criterios y publícala antes de programar capturas." /></div>}
        </div>
        <div className="mt-5 flex gap-3 rounded-2xl border border-[#c9dce5] bg-[#f7fbfd] p-4 text-sm text-[#557083]"><ShieldCheck className="mt-0.5 size-5 shrink-0 text-[#168b95]" /><p>{snapshot.regulatoryNote}</p></div>
      </section>}
    </div>

    {recurrenceOpen && <Modal title="Nueva recurrencia" onClose={() => setRecurrenceOpen(false)}><div className="grid gap-4"><FieldLabel label="Sucursal"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={recurrence.branchId} onChange={(event) => setRecurrence((current) => ({ ...current, branchId: event.target.value, templateVersionId: "", shiftId: "" }))}>{snapshot.branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></FieldLabel><FieldLabel label="Plantilla publicada"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={recurrence.templateVersionId} onChange={(event) => setRecurrence((current) => ({ ...current, templateVersionId: event.target.value }))}><option value="">Selecciona</option>{publishedVersions.filter((version) => !recurrence.branchId || !version.rootBranchId || version.rootBranchId === recurrence.branchId).map((version) => <option key={version.id} value={version.id}>{version.name} · v{version.versionNumber}</option>)}</select></FieldLabel><FieldLabel label="Frecuencia"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={recurrence.scheduleType} onChange={(event) => setRecurrence((current) => ({ ...current, scheduleType: event.target.value as RecurrenceDraft["scheduleType"], timesText: event.target.value === "multiple_daily" ? "08:00, 12:00, 16:00" : event.target.value === "interval" ? "08:00, 16:00" : current.timesText.split(",")[0]?.trim() || "12:00" }))}><option value="daily">Diaria</option><option value="per_shift">Por turno</option><option value="days">Días específicos</option><option value="multiple_daily">Varias veces al día</option><option value="interval">Por intervalo</option></select></FieldLabel>{recurrence.scheduleType === "per_shift" && <FieldLabel label="Turno"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={recurrence.shiftId} onChange={(event) => setRecurrence((current) => ({ ...current, shiftId: event.target.value }))}><option value="">Selecciona</option>{snapshot.shifts.filter((shift) => !recurrence.branchId || !shift.branchId || shift.branchId === recurrence.branchId).map((shift) => <option key={shift.id} value={shift.id}>{shift.name}</option>)}</select></FieldLabel>}{recurrence.scheduleType === "days" && <div><span className="mb-2 block text-sm font-bold text-[#36536a]">Días de la semana</span><div className="grid grid-cols-4 gap-2 sm:grid-cols-7">{[0,1,2,3,4,5,6].map((day) => <label key={day} className={`cursor-pointer rounded-xl border p-2 text-center text-xs font-bold ${recurrence.daysOfWeek.includes(day) ? "border-[#168b95] bg-[#e8f7f6] text-[#116c73]" : "border-[#d4e2e8] bg-white text-[#657b8d]"}`}><input type="checkbox" className="sr-only" checked={recurrence.daysOfWeek.includes(day)} onChange={(event) => setRecurrence((current) => ({ ...current, daysOfWeek: event.target.checked ? [...current.daysOfWeek, day].sort() : current.daysOfWeek.filter((value) => value !== day) }))} />{dayLabel(day)}</label>)}</div></div>}<FieldLabel label={recurrence.scheduleType === "interval" ? "Hora inicial, hora final" : recurrence.scheduleType === "multiple_daily" ? "Horas separadas por coma" : "Hora límite"}><Input className="h-11 rounded-xl" value={recurrence.timesText} onChange={(event) => setRecurrence((current) => ({ ...current, timesText: event.target.value }))} placeholder={recurrence.scheduleType === "multiple_daily" ? "08:00, 12:00, 16:00" : recurrence.scheduleType === "interval" ? "08:00, 16:00" : "12:00"} /></FieldLabel>{recurrence.scheduleType === "interval" && <FieldLabel label="Intervalo en minutos"><Input type="number" min={15} max={720} className="h-11 rounded-xl" value={recurrence.intervalMinutes} onChange={(event) => setRecurrence((current) => ({ ...current, intervalMinutes: event.target.value }))} /></FieldLabel>}<div className="grid grid-cols-2 gap-3"><FieldLabel label="Empieza"><Input type="date" className="h-11 rounded-xl" value={recurrence.startDate} onChange={(event) => setRecurrence((current) => ({ ...current, startDate: event.target.value }))} /></FieldLabel><FieldLabel label="Termina (opcional)"><Input type="date" className="h-11 rounded-xl" value={recurrence.endDate} onChange={(event) => setRecurrence((current) => ({ ...current, endDate: event.target.value }))} /></FieldLabel></div><p className="text-xs leading-5 text-[#718699]">La zona horaria se toma de la sucursal. Al guardar se genera una primera ventana segura; después puede avanzarse de 7 en 7 días sin duplicados.</p><Button className="min-h-12 rounded-xl bg-[#0b8f87] font-extrabold" disabled={busy || !recurrence.templateVersionId || !recurrence.startDate} onClick={() => void createRecurrence()}>{busy ? <Loader2 className="size-4 animate-spin" /> : <CalendarClock className="size-4" />}Crear recurrencia</Button></div></Modal>}

    {scheduleOpen && <Modal title="Programar bitácora" onClose={() => setScheduleOpen(false)}><div className="grid gap-4"><FieldLabel label="Sucursal"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={schedule.branchId} onChange={(event) => setSchedule((current) => ({ ...current, branchId: event.target.value, templateVersionId: "", shiftId: "" }))}>{snapshot.branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></FieldLabel><FieldLabel label="Plantilla publicada"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={schedule.templateVersionId} onChange={(event) => setSchedule((current) => ({ ...current, templateVersionId: event.target.value, shiftId: "" }))}><option value="">Selecciona</option>{applicableTemplates.map((version) => <option key={version.id} value={version.id}>{version.name} · v{version.versionNumber}</option>)}</select></FieldLabel>{selectedScheduleTemplate?.scheduleType === "per_shift" && <FieldLabel label="Turno"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={schedule.shiftId} onChange={(event) => setSchedule((current) => ({ ...current, shiftId: event.target.value }))}><option value="">Selecciona</option>{applicableShifts.map((shift) => <option key={shift.id} value={shift.id}>{shift.name}</option>)}</select></FieldLabel>}<div className="grid grid-cols-2 gap-3"><FieldLabel label="Fecha operativa"><Input type="date" className="h-11 rounded-xl" value={schedule.operationalDate} onChange={(event) => setSchedule((current) => ({ ...current, operationalDate: event.target.value }))} /></FieldLabel><FieldLabel label="Hora límite"><Input type="time" className="h-11 rounded-xl" value={schedule.dueTime} onChange={(event) => setSchedule((current) => ({ ...current, dueTime: event.target.value }))} /></FieldLabel></div><p className="text-xs text-[#718699]">La hora se interpreta en la zona de la sucursal seleccionada.</p><Button className="min-h-12 rounded-xl bg-[#1769df] font-extrabold" disabled={busy || !schedule.templateVersionId} onClick={() => void scheduleLog()}>{busy ? <Loader2 className="size-4 animate-spin" /> : <CalendarClock className="size-4" />}Programar y abrir</Button></div></Modal>}

    {templateDraft && <Modal title={templateDraft.templateVersionId ? "Editar borrador" : templateDraft.rootTemplateId ? "Estructurar plantilla" : "Nueva plantilla"} wide onClose={() => setTemplateDraft(null)}><TemplateEditor value={templateDraft} branches={snapshot.branches} lockScope={Boolean(templateDraft.rootTemplateId)} onChange={setTemplateDraft} /><div className="mt-5 flex justify-end"><Button className="min-h-12 rounded-xl bg-[#0b8f87] px-7 font-extrabold" disabled={busy || templateDraft.name.trim().length < 2 || templateDraft.fields.length < 1} onClick={() => void saveTemplate()}>{busy ? <Loader2 className="size-4 animate-spin" /> : <Settings2 className="size-4" />}Guardar borrador</Button></div></Modal>}

    {revision && <Modal title="Crear nueva versión" onClose={() => setRevision(null)}><p className="text-sm leading-6 text-[#6b8093]">Se copiarán los campos de la versión {revision.version.versionNumber}. La versión publicada seguirá intacta.</p><FieldLabel label="Motivo del cambio"><Textarea className="mt-2 rounded-xl" value={revision.reason} onChange={(event) => setRevision({ ...revision, reason: event.target.value })} /></FieldLabel><Button className="mt-4 min-h-11 w-full rounded-xl" disabled={busy || revision.reason.trim().length < 5} onClick={() => void perform(async () => { const result = await qualityMutation<{ templateVersionId: string }>("create_template_revision", { organizationId: snapshot.organization.id, templateVersionId: revision.version.id, reason: revision.reason, idempotencyKey: crypto.randomUUID() }); const next = { ...revision.version, id: result.templateVersionId, versionNumber: revision.version.versionNumber + 1, version: 1, status: "draft" as const, publishedAt: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }; setRevision(null); openDraft(next); }, "La nueva versión quedó en borrador.")}>Crear borrador versionado</Button></Modal>}
  </main>;
}

function TemplateEditor({ value, branches, lockScope, onChange }: { value: TemplateDraft; branches: QualitySnapshot["branches"]; lockScope: boolean; onChange: (value: TemplateDraft) => void }) {
  const set = <K extends keyof TemplateDraft>(key: K, next: TemplateDraft[K]) => onChange({ ...value, [key]: next });
  const updateField = (key: string, patch: Partial<FieldDraft>) => set("fields", value.fields.map((field) => field.key === key ? { ...field, ...patch } : field));
  return <div className="space-y-5"><div className="grid gap-4 sm:grid-cols-2"><FieldLabel label="Nombre"><Input className="h-11 rounded-xl" value={value.name} disabled={lockScope && !value.templateVersionId} onChange={(event) => set("name", event.target.value)} /></FieldLabel><FieldLabel label="Código"><Input className="h-11 rounded-xl uppercase" value={value.code} disabled={lockScope && !value.templateVersionId} onChange={(event) => set("code", event.target.value)} /></FieldLabel><FieldLabel label="Aplicación"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={value.branchId} disabled={lockScope || Boolean(value.templateVersionId)} onChange={(event) => set("branchId", event.target.value)}><option value="all">Todas las sucursales</option>{branches.map((branch) => <option key={branch.id} value={branch.id}>{branch.name}</option>)}</select></FieldLabel><FieldLabel label="Categoría"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={value.category} onChange={(event) => set("category", event.target.value)}><option value="temperature">Temperaturas</option><option value="water">Cloro y pH</option><option value="receiving">Recepción</option><option value="cleaning">Limpieza</option><option value="hygiene">Higiene</option><option value="other">Otro control</option></select></FieldLabel><FieldLabel label="Frecuencia"><select className="h-11 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={value.scheduleType} onChange={(event) => set("scheduleType", event.target.value)}><option value="adhoc">Cuando se necesite</option><option value="daily">Diaria</option><option value="per_shift">Por turno</option><option value="days">Días específicos</option><option value="multiple_daily">Varias veces al día</option><option value="interval">Intervalo</option></select></FieldLabel><FieldLabel label="Hora sugerida"><Input type="time" className="h-11 rounded-xl" value={value.defaultDueTime} onChange={(event) => set("defaultDueTime", event.target.value)} /></FieldLabel></div><FieldLabel label="Instrucciones"><Textarea className="mt-2 rounded-xl" value={value.instructions} onChange={(event) => set("instructions", event.target.value)} placeholder="Indica dónde, cómo y con qué instrumento debe realizarse el control." /></FieldLabel><div><div className="flex items-center justify-between"><div><h3 className="font-black">Campos y criterios</h3><p className="mt-1 text-xs text-[#718699]">Los rangos publicados se evalúan en el servidor.</p></div><Button variant="outline" size="sm" className="rounded-lg" onClick={() => set("fields", [...value.fields, emptyField("", "number", "")])}><Plus className="size-3.5" />Campo</Button></div><div className="mt-3 space-y-3">{value.fields.map((field, index) => <div key={field.key} className="rounded-2xl border border-[#d8e5eb] bg-[#f8fbfc] p-4"><div className="flex items-center justify-between gap-3"><strong className="text-sm">Campo {index + 1}</strong>{value.fields.length > 1 && <Button variant="ghost" size="icon-sm" onClick={() => set("fields", value.fields.filter((item) => item.key !== field.key))} aria-label="Quitar campo"><X className="size-4" /></Button>}</div><div className="mt-3 grid gap-3 sm:grid-cols-2"><FieldLabel label="Nombre"><Input className="h-10 rounded-xl bg-white" value={field.label} onChange={(event) => updateField(field.key, { label: event.target.value })} /></FieldLabel><FieldLabel label="Tipo"><select className="h-10 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={field.fieldType} onChange={(event) => updateField(field.key, { fieldType: event.target.value as OperationalQualityFieldType })}><option value="number">Número o medición</option><option value="boolean">Sí / No</option><option value="select">Lista de opciones</option><option value="text">Texto</option></select></FieldLabel><FieldLabel label="Descripción"><Input className="h-10 rounded-xl bg-white" value={field.description} onChange={(event) => updateField(field.key, { description: event.target.value })} /></FieldLabel><FieldLabel label="Código"><Input className="h-10 rounded-xl bg-white uppercase" value={field.code} onChange={(event) => updateField(field.key, { code: event.target.value })} /></FieldLabel>{field.fieldType === "number" && <><FieldLabel label="Unidad"><Input className="h-10 rounded-xl bg-white" value={field.unit} onChange={(event) => updateField(field.key, { unit: event.target.value })} placeholder="°C, ppm, pH" /></FieldLabel><div className="grid grid-cols-2 gap-2"><FieldLabel label="Mínimo"><Input type="number" step="any" className="h-10 rounded-xl bg-white" value={field.minimum} onChange={(event) => updateField(field.key, { minimum: event.target.value })} /></FieldLabel><FieldLabel label="Máximo"><Input type="number" step="any" className="h-10 rounded-xl bg-white" value={field.maximum} onChange={(event) => updateField(field.key, { maximum: event.target.value })} /></FieldLabel></div></>}{field.fieldType === "boolean" && <FieldLabel label="Respuesta conforme"><select className="h-10 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={String(field.expectedBoolean)} onChange={(event) => updateField(field.key, { expectedBoolean: event.target.value === "true" })}><option value="true">Sí</option><option value="false">No</option></select></FieldLabel>}{field.fieldType === "select" && <><FieldLabel label="Opciones separadas por coma"><Input className="h-10 rounded-xl bg-white" value={field.options} onChange={(event) => updateField(field.key, { options: event.target.value })} /></FieldLabel><FieldLabel label="Opciones no conformes"><Input className="h-10 rounded-xl bg-white" value={field.nonCompliantOptions} onChange={(event) => updateField(field.key, { nonCompliantOptions: event.target.value })} /></FieldLabel></>}<FieldLabel label="Severidad"><select className="h-10 w-full rounded-xl border border-[#ccdbe4] bg-white px-3 text-sm" value={field.severity} onChange={(event) => updateField(field.key, { severity: event.target.value as "warning" | "critical" })}><option value="warning">Advertencia</option><option value="critical">Crítica</option></select></FieldLabel><div className="space-y-2 self-end pb-1"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={field.required} onChange={(event) => updateField(field.key, { required: event.target.checked })} />Obligatorio</label><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={field.evidenceRequired} onChange={(event) => updateField(field.key, { evidenceRequired: event.target.checked })} />Exigir evidencia si se desvía</label></div></div></div>)}</div></div></div>;
}

function templatePayload(organizationId: string, draft: TemplateDraft) { return { organizationId, code: draft.code, name: draft.name, category: draft.category, instructions: draft.instructions, scheduleType: draft.scheduleType, defaultDueTime: draft.defaultDueTime || null, fields: draft.fields.map((field) => ({ code: field.code || undefined, label: field.label, description: field.description, fieldType: field.fieldType, unit: field.unit || null, required: field.required, minimum: field.fieldType === "number" && field.minimum !== "" ? Number(field.minimum) : null, maximum: field.fieldType === "number" && field.maximum !== "" ? Number(field.maximum) : null, expectedBoolean: field.fieldType === "boolean" ? field.expectedBoolean : null, options: split(field.options), nonCompliantOptions: split(field.nonCompliantOptions), deviationSeverity: field.severity, evidenceRequiredOnDeviation: field.evidenceRequired })) }; }
function emptyField(label: string, fieldType: OperationalQualityFieldType, unit: string): FieldDraft { return { key: crypto.randomUUID(), code: "", label, description: "", fieldType, unit, minimum: "", maximum: "", expectedBoolean: true, options: "Conforme, No conforme", nonCompliantOptions: "No conforme", required: true, severity: "warning", evidenceRequired: false }; }
function split(value: string) { return value.split(",").map((item) => item.trim()).filter(Boolean); }
function todayInput() { const date = new Date(); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}-${String(date.getDate()).padStart(2, "0")}`; }
function zonedDateTimeToIso(date: string, time: string, timezone: string) {
  const [year, month, day] = date.split("-").map(Number);
  const [hour, minute] = time.split(":").map(Number);
  const target = Date.UTC(year, month - 1, day, hour, minute, 0);
  let guess = target;
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const parts = Object.fromEntries(new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23" }).formatToParts(new Date(guess)).map((part) => [part.type, part.value]));
    const observed = Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day), Number(parts.hour), Number(parts.minute), Number(parts.second));
    guess += target - observed;
  }
  return new Date(guess).toISOString();
}
function SummaryCard({ label, value }: { label: string; value: string }) { return <div className="rounded-xl bg-[#f5f9fb] p-3"><span className="block text-[10px] font-extrabold uppercase tracking-wide text-[#718699]">{label}</span><strong className="mt-1 block text-sm text-[#24445e]">{value}</strong></div>; }
function recurrenceLabel(type: string) { return ({ daily: "Diaria", per_shift: "Por turno", days: "Días específicos", multiple_daily: "Varias al día", interval: "Intervalo", adhoc: "Ad hoc" } as Record<string, string>)[type] ?? type; }
function dayLabel(day: number) { return ["Dom", "Lun", "Mar", "Mié", "Jue", "Vie", "Sáb"][day] ?? String(day); }
function addDaysInput(value: string, days: number) { const date = new Date(`${value}T00:00:00.000Z`); date.setUTCDate(date.getUTCDate() + days); return date.toISOString().slice(0, 10); }
function minDate(a: string, b: string) { return a <= b ? a : b; }
function HeroMetric({ value, label }: { value: number; label: string }) { return <div className="min-w-25 rounded-2xl bg-white/10 p-3 text-center"><strong className="block text-2xl font-black">{value.toLocaleString("es-MX")}</strong><span className="mt-1 block text-[10px] font-bold uppercase tracking-wide text-[#b9ccd8]">{label}</span></div>; }
function Metric({ icon: Icon, label, value, alert = false }: { icon: typeof Gauge; label: string; value: number | string; alert?: boolean }) { return <article className={`rounded-[1.3rem] border bg-white p-4 shadow-sm ${alert ? "border-[#efc3b4]" : "border-[#d5e4eb]"}`}><div className={`flex size-9 items-center justify-center rounded-xl ${alert ? "bg-[#fff0ea] text-[#c25436]" : "bg-[#e8f5f4] text-[#148a93]"}`}><Icon className="size-4" /></div><strong className="mt-3 block text-2xl font-black">{typeof value === "number" ? value.toLocaleString("es-MX") : value}</strong><span className="mt-1 block text-xs text-[#718699]">{label}</span></article>; }
function TabButton({ active, onClick, icon: Icon, label, count }: { active: boolean; onClick: () => void; icon: typeof Gauge; label: string; count: number }) { return <button type="button" onClick={onClick} className={`flex min-h-11 shrink-0 items-center gap-2 rounded-xl px-4 text-sm font-bold transition ${active ? "bg-[#123e5d] text-white" : "text-[#5e7689] hover:bg-[#edf5f7]"}`}><Icon className="size-4" />{label}<span className={`rounded-full px-2 py-0.5 text-xs ${active ? "bg-white/15" : "bg-[#e6eff3]"}`}>{count}</span></button>; }
function Empty({ icon: Icon, title, detail }: { icon: typeof Gauge; title: string; detail: string }) { return <div className="mt-4 rounded-[1.4rem] border border-dashed border-[#bcd0da] bg-white/70 p-9 text-center"><Icon className="mx-auto size-7 text-[#3c9ca2]" /><p className="mt-3 font-black">{title}</p><p className="mt-2 text-sm text-[#6a8093]">{detail}</p></div>; }
function Notice({ tone, text }: { tone: "error" | "success" | "info"; text: string }) { const styles = tone === "error" ? "border-[#efc6b8] bg-[#fff7f3] text-[#8d422b]" : tone === "success" ? "border-[#b8dfd3] bg-[#f0fbf7] text-[#176c58]" : "border-[#b8d6e8] bg-[#edf7fd] text-[#255f82]"; const Icon = tone === "error" ? AlertTriangle : tone === "success" ? CheckCircle2 : ShieldCheck; return <div className={`flex gap-3 rounded-2xl border p-4 text-sm ${styles}`}><Icon className="mt-0.5 size-5 shrink-0" /><p>{text}</p></div>; }
function Modal({ title, children, onClose, wide = false }: { title: string; children: React.ReactNode; onClose: () => void; wide?: boolean }) { return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#071e31]/60 p-3 backdrop-blur-sm" role="dialog" aria-modal="true"><div className={`mx-auto my-5 rounded-[1.6rem] bg-white p-5 shadow-2xl sm:p-7 ${wide ? "max-w-4xl" : "max-w-xl"}`}><div className="flex items-center justify-between gap-3"><h2 className="text-2xl font-black">{title}</h2><Button variant="ghost" size="icon" className="rounded-xl" onClick={onClose} aria-label="Cerrar"><X className="size-5" /></Button></div><div className="mt-5">{children}</div></div></div>; }
function FieldLabel({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block"><span className="mb-2 block text-sm font-bold text-[#36536a]">{label}</span>{children}</label>; }
function FullState({ loading = false, title, detail }: { loading?: boolean; title: string; detail: string }) { return <main className="flex min-h-screen items-center justify-center bg-[#edf4f7] p-5"><div className="w-full max-w-md rounded-[1.8rem] border border-[#d2e2e9] bg-white p-8 text-center shadow-[0_25px_70px_rgba(22,55,84,.1)]"><BrandMark /><div className="mx-auto mt-8 flex size-12 items-center justify-center rounded-2xl bg-[#e8f3ff] text-[#1769df]">{loading ? <Loader2 className="size-6 animate-spin" /> : <AlertTriangle className="size-6" />}</div><h1 className="mt-5 text-2xl font-black">{title}</h1><p className="mt-2 text-sm leading-6 text-[#6b8093]">{detail}</p><Button asChild variant="outline" className="mt-6 rounded-xl"><Link href="/">Volver al acceso</Link></Button></div></main>; }
function statusLabel(status: string) { return ({ pending: "Pendiente", upcoming: "Próxima", in_progress: "En captura", overdue: "Vencida", completed: "Cerrada", corrected: "Corregida", cancelled: "Cancelada" } as Record<string, string>)[status] ?? status; }
function correctiveStatusLabel(status: string) { return ({ open: "Abierta", assigned: "Asignada", in_progress: "En seguimiento", overdue: "Vencida", resolved: "Resuelta · por verificar", verified: "Verificada", cancelled: "Cancelada" } as Record<string, string>)[status] ?? status; }
function categoryLabel(category: string) { return ({ temperature: "Temperaturas", water: "Cloro y pH", receiving: "Recepción", cleaning: "Limpieza", hygiene: "Higiene", other: "Otro" } as Record<string, string>)[category] ?? category; }
function templateStatusLabel(status: string) { return ({ draft: "Borrador", published: "Publicada", archived: "Histórica" } as Record<string, string>)[status] ?? status; }
function templateStatusStyle(status: string) { return status === "published" ? "bg-[#dff5eb] text-[#14745c]" : status === "archived" ? "bg-[#e7edf1] text-[#526a7b]" : "bg-[#fff0cd] text-[#7b570b]"; }
